    {
      "option": "A",
      "correct": false,
      "reason": "Khai triển phương án A cho ra A^2 + 2AB + B^2, khác với biểu thức A^2 - B^2 trong đề."
    },
    {
      "option": "B",
      "correct": false,
      "reason": "Khai triển phương án B cho ra A^2 - 2AB + B^2, khác với biểu thức A^2 - B^2 trong đề."
    },
    {
      "option": "C",
      "correct": true,
      "reason": "Khai triển phương án C bằng cách nhân đa thức với đa thức ta được A^2 - AB + AB - B^2 = A^2 - B^2, đúng bằng biểu thức của đề."
    },
    {
      "option": "D",
      "correct": false,
      "reason": "Phương án D là hằng đẳng thức bình phương của một hiệu, khác với hiệu hai bình phương trong đề."
